using Godot;
using System;
namespace MySim {
// Independent engine geometry invariant: Godot front faces are clockwise, opposite outward vertex normals.
public static class GeneratedWheelGeometryChecks {
 static int Check(Mesh mesh){int triangles=0;for(int surface=0;surface<mesh.GetSurfaceCount();surface++){using var arrays=mesh.SurfaceGetArrays(surface);var vertices=(Vector3[])arrays[(int)Mesh.ArrayType.Vertex];var normals=(Vector3[])arrays[(int)Mesh.ArrayType.Normal];var indices=(int[])arrays[(int)Mesh.ArrayType.Index];if(indices!=null&&indices.Length==0)indices=null;int count=indices?.Length??vertices.Length;for(int i=0;i+2<count;i+=3){int a=indices==null?i:indices[i],b=indices==null?i+1:indices[i+1],c=indices==null?i+2:indices[i+2];var cross=(vertices[b]-vertices[a]).Cross(vertices[c]-vertices[a]);if(cross.LengthSquared()<1e-14f)continue;float facing=cross.Normalized().Dot((normals[a]+normals[b]+normals[c]).Normalized());if(facing>0.001f)throw new Exception("Generated wheel triangle faces inward relative to engine winding: surface="+surface+" triangle="+(i/3));triangles++;}}if(triangles==0)throw new Exception("Generated wheel has no valid triangles");return triangles;}
 static int BrakeChecks(Node owner){
  string previous=System.Environment.GetEnvironmentVariable("MYSIM_REBUILT_BRAKES");var wheel=new Node3D();owner.AddChild(wheel);var spin=new Node3D();var fixedBrake=new Node3D();wheel.AddChild(spin);wheel.AddChild(fixedBrake);int triangles=0;
  try{System.Environment.SetEnvironmentVariable("MYSIM_REBUILT_BRAKES","1");WheelRimBuilder.BrakeCandidate(spin,fixedBrake,.2f,.3f);var rotor=spin.GetNode<Node3D>("RebuiltVentilatedBrake");var caliper=fixedBrake.GetNode<Node3D>("RebuiltFixedCaliper");var before=caliper.GlobalTransform;var rotorBefore=rotor.GlobalBasis;spin.Rotation=new Vector3(.7f,0,0);
   if(!caliper.GlobalTransform.IsEqualApprox(before)||rotor.GlobalBasis.IsEqualApprox(rotorBefore))throw new Exception("Brake rotor/caliper kinematics incorrect");
   var inverse=wheel.GlobalTransform.AffineInverse();var nodes=wheel.FindChildren("*","MeshInstance3D",true,false);foreach(var node in nodes){var mesh=(MeshInstance3D)node;triangles+=Check(mesh.Mesh);var transform=inverse*mesh.GlobalTransform;for(int surface=0;surface<mesh.Mesh.GetSurfaceCount();surface++){using var arrays=mesh.Mesh.SurfaceGetArrays(surface);foreach(var point in arrays[(int)Mesh.ArrayType.Vertex].AsVector3Array()){var v=transform*point;if(Mathf.Abs(v.X)>.15f||new Vector2(v.Y,v.Z).Length()>.2f)throw new Exception("Brake candidate exceeds recovered test rim envelope");}}}nodes.Clear();
   GD.Print("PASS brake candidate winding, rim envelope and stationary-caliper/spinning-rotor separation");return triangles;
  }finally{System.Environment.SetEnvironmentVariable("MYSIM_REBUILT_BRAKES",previous);wheel.QueueFree();}
 }
 public static void Run(Node owner){int triangles=BrakeChecks(owner);foreach(bool wet in new[]{false,true}){using var mesh=TyreMeshBuilder.Build(.33f,.3f,wet);triangles+=Check(mesh);}for(int design=0;design<3;design++){var rim=WheelRimBuilder.Build(.2f,.3f,design);owner.AddChild(rim);var nodes=rim.FindChildren("*","MeshInstance3D",true,false);foreach(var node in nodes)triangles+=Check(((MeshInstance3D)node).Mesh);nodes.Clear();rim.QueueFree();}for(int car=15;car<=18;car++){var rim=WheelRimBuilder.Build(.2f,.3f,2,car);owner.AddChild(rim);int spokes=0,nuts=0;foreach(var node in rim.GetChildren())if(node is MeshInstance3D mesh){triangles+=Check(mesh.Mesh);if(mesh.Name.ToString().StartsWith("ForgedSpoke"))spokes++;if(mesh.Name.ToString().StartsWith("LugNut"))nuts++;}if(spokes!=10||nuts!=1||rim.GetMeta("custom_f1_car").AsInt32()!=car)throw new Exception("Custom F1 wheel hardware/profile mismatch");rim.QueueFree();}GD.Print("PASS generated tyre/rim outward normals and clockwise winding triangles=",triangles);}
}
}
